questionvariables.text:
/* Design: classify-the-objects pattern. Source: original. Items: I1 (x+c1)^n1 or (x-c1)^n1; I2 (c2-x)^3; I3 (-x-c3)^m3, m3 even; I4 (c4-x)^4 or (-x-c4)^3. Categories A all +, B alternate from +, C alternate from -, D all -. */
L: [[1,3,4,2,4,2,0,5,[2,4,1,3]],[-1,2,3,5,3,4,1,2,[3,1,4,2]],[1,5,3,3,2,4,1,4,[4,2,3,1]],[-1,4,4,2,5,2,0,3,[2,3,1,4]],[1,2,4,4,3,2,1,5,[3,4,2,1]],[-1,3,3,5,2,4,0,2,[4,1,2,3]],[1,4,3,3,4,2,0,5,[1,3,4,2]],[-1,5,4,2,3,4,1,3,[2,1,3,4]],[1,3,3,4,5,2,1,2,[3,2,4,1]],[-1,2,4,3,4,4,0,4,[4,3,1,2]]];
ix: 1+rand(10);
s1: L[ix][1]; c1: L[ix][2]; n1: L[ix][3]; c2: L[ix][4]; c3: L[ix][5]; m3: L[ix][6]; f4: L[ix][7]; c4: L[ix][8]; perm: L[ix][9];
it: [sconcat("\\left(x",if s1=1 then "+" else "-",c1,"\\right)^{",n1,"}"), sconcat("\\left(",c2,"-x\\right)^{3}"), sconcat("\\left(-x-",c3,"\\right)^{",m3,"}"),
     if f4=0 then sconcat("\\left(",c4,"-x\\right)^{4}") else sconcat("\\left(-x-",c4,"\\right)^{3}")];
E: [(x+s1*c1)^n1, (c2-x)^3, (-x-c3)^m3, if f4=0 then (c4-x)^4 else (-x-c4)^3];
EX: map(expand, E);
cat: [if s1=1 then "A" else "B", "C", "A", if f4=0 then "B" else "D"];
nm: ["all positive", "alternate, starting with \\(+\\)", "alternate, starting with \\(-\\)", "all negative"];
catn: makelist(nm[if cat[j]="A" then 1 else if cat[j]="B" then 2 else if cat[j]="C" then 3 else 4], j, 1, 4);
mkopt(k) := [[sconcat("A",k), is(cat[perm[k]]="A"), "All positive"], [sconcat("B",k), is(cat[perm[k]]="B"), "Alternate, starting with +"], [sconcat("C",k), is(cat[perm[k]]="C"), "Alternate, starting with −"], [sconcat("D",k), is(cat[perm[k]]="D"), "All negative"]];
opt1: mkopt(1); opt2: mkopt(2); opt3: mkopt(3); opt4: mkopt(4);
shown: makelist(it[perm[k]],k,1,4);
kq: makelist(sconcat(cat[perm[k]],k),k,1,4);
p1: first(sublist_indices(perm, lambda([v], is(v=1))));
p2: first(sublist_indices(perm, lambda([v], is(v=2))));
p3: first(sublist_indices(perm, lambda([v], is(v=3))));
t2: makelist(if k=p2 then sconcat("B",k) else kq[k],k,1,4);
t3: makelist(if k=p3 then sconcat("D",k) else kq[k],k,1,4);
t4: makelist(if k=p1 then sconcat("D",k) else kq[k],k,1,4);
it2: it[2]; it3: it[3];
keyd: simplode(makelist(sconcat("(",k,") ",catn[perm[k]]),k,1,4), ", ");

feedbackvariables.text:
got: [ans1,ans2,ans3,ans4];
nc: apply("+", makelist(if is(got[k]=kq[k]) then 1 else 0, k, 1, 4));
d1: is(got[p2]=sconcat("B",p2));
d3: is(got[p3]=sconcat("D",p3));
